import{_ as t,a,c as s,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"程序员英语 04：读报错、搜索与求助","description":"拆解英文错误信息，区分现象和原因，并用环境、复现与证据组织搜索和求助文本。","frontmatter":{"title":"程序员英语 04：读报错、搜索与求助","description":"拆解英文错误信息，区分现象和原因，并用环境、复现与证据组织搜索和求助文本。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"程序员英语","summary":"拆解英文错误信息，区分现象和原因，并用环境、复现与证据组织搜索和求助文本。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs"},"next":{"text":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs"},"next":{"text":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr"}},"headers":[],"relativePath":"life/english/programmer/errors-search.md","filePath":"life/english/programmer/errors-search.md"}'),i={name:"life/english/programmer/errors-search.md"};function o(r,e,p,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="程序员英语-04-读报错、搜索与求助" tabindex="-1">程序员英语 04：读报错、搜索与求助 <a class="header-anchor" href="#程序员英语-04-读报错、搜索与求助" aria-label="Permalink to &quot;程序员英语 04：读报错、搜索与求助&quot;">​</a></h1><p>看到 <code>Permission denied</code> 就重装软件，通常跳过了最有价值的信息：谁对哪个资源做什么时被拒绝。英文报错阅读可以先拆成“动作、对象、失败条件”，再沿调用链寻找证据。</p><h2 id="逐层拆开错误" tabindex="-1">逐层拆开错误 <a class="header-anchor" href="#逐层拆开错误" aria-label="Permalink to &quot;逐层拆开错误&quot;">​</a></h2><p>下面是原创的虚构转换器日志：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export failed: could not open output/report.csv: permission denied</span></span></code></pre></div><p>最外层 <code>export failed</code> 是用户可见任务；<code>could not open</code> 是失败动作；<code>output/report.csv</code> 是目标；<code>permission denied</code> 是操作系统返回的原因类别。它并不直接证明是哪一种权限配置出错，也不能证明导出代码本身没有问题。</p><p>先写一个准确的英文复述：<code>The export fails when the tool opens the output file.</code> 再写假设：<code>The process may not have write access to the output directory.</code> 第一行是现象，第二行有 <code>may</code>，说明尚待验证。</p><table tabindex="0"><thead><tr><th>常见表达</th><th>能说明什么</th><th>不能单独证明什么</th></tr></thead><tbody><tr><td>not found</td><td>某个查找没有找到目标</td><td>目标一定从未存在</td></tr><tr><td>timed out</td><td>在限定时间内未完成</td><td>远端已经宕机</td></tr><tr><td>connection refused</td><td>连接遭到拒绝</td><td>唯一原因就是防火墙</td></tr><tr><td>invalid argument</td><td>参数不被接受</td><td>所有参数都错误</td></tr><tr><td>out of memory</td><td>某次内存需求未能满足</td><td>一定存在内存泄漏</td></tr></tbody></table><h2 id="搜索时保留稳定信息" tabindex="-1">搜索时保留稳定信息 <a class="header-anchor" href="#搜索时保留稳定信息" aria-label="Permalink to &quot;搜索时保留稳定信息&quot;">​</a></h2><p>好的搜索式包含工具名、版本或平台、错误中的稳定片段。例如虚构工具 <code>filepack</code> 的问题可以先搜：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filepack &quot;permission denied&quot; output Windows</span></span>
<span class="line"><span>filepack output directory permissions documentation</span></span></code></pre></div><p>引号适合短且稳定的错误片段。先去掉随机文件名、请求 ID、时间戳等噪声，但在本地保留完整日志。结果太少时逐步放宽，不要把整个多行堆栈一次塞进搜索框。</p><p>阅读搜索结果时，核对版本和触发条件；“有人重装后解决”不等于找到了你的原因。可优先查官方排障文档，再看维护者确认的 Issue。对答案中的命令，先理解作用与影响，再决定是否适用于自己的环境。</p><h2 id="求助文本-让对方能开始验证" tabindex="-1">求助文本：让对方能开始验证 <a class="header-anchor" href="#求助文本-让对方能开始验证" aria-label="Permalink to &quot;求助文本：让对方能开始验证&quot;">​</a></h2><p>下面的数据全部为教学假设：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I am using filepack 2.4 on Windows 11.</span></span>
<span class="line"><span>Exporting to output/report.csv fails with &quot;permission denied&quot;.</span></span>
<span class="line"><span>Exporting the same input to a directory I own succeeds.</span></span>
<span class="line"><span>I expected the tool to create the report in either directory.</span></span>
<span class="line"><span>Could you help me identify which permissions the output directory needs?</span></span></code></pre></div><p>第一句给环境，第二句给现象，第三句给对照实验，第四句给预期，第五句给具体问题。若还没做过第三句的实验，就改成计划 <code>I will check whether exporting to a directory I own succeeds.</code>，不能为了让求助显得完整而编造测试结果。</p><h2 id="练习-改写一个模糊问题" tabindex="-1">练习：改写一个模糊问题 <a class="header-anchor" href="#练习-改写一个模糊问题" aria-label="Permalink to &quot;练习：改写一个模糊问题&quot;">​</a></h2><p>原文：<code>It doesn&#39;t work. I think your code is broken. Please fix it.</code></p><p>已知信息：虚构工具 2.4；输入有一条空记录；默认模式退出；删除空记录后可完成；预期跳过空记录。写 4～6 句英文求助，并提出一个尚待核对的问题。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p>一种答案：</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>With filepack 2.4, the import exits when the input contains an empty record.</span></span>
<span class="line"><span>Removing that record allows the import to finish.</span></span>
<span class="line"><span>I expected the default mode to skip empty records.</span></span>
<span class="line"><span>I have attached a minimal input with the same behavior.</span></span>
<span class="line"><span>Does this version distinguish an empty record from a blank line?</span></span></code></pre></div><p>最后一句没有断言程序一定错误，而是询问术语边界。真实使用时，仅在实际附上材料后保留 <code>I have attached</code>。原题未提供平台，不能随意补写。</p></details><h2 id="资料与延伸" tabindex="-1">资料与延伸 <a class="header-anchor" href="#资料与延伸" aria-label="Permalink to &quot;资料与延伸&quot;">​</a></h2><p><a href="https://developers.google.com/tech-writing/error-messages" target="_blank" rel="noopener noreferrer">Google 错误信息写作课程</a> 从错误信息的读者出发，讨论如何说明问题与解决办法。反过来阅读日志时，也可以检查消息缺少的是失败对象、条件还是下一步。</p>`,23)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
